func main() {
    // Read the book "The Great Gatsby"
    book, err := os.Open("The_Great_Gatsby.txt")
    if err != nil {
        log.Fatal(err)
    }
    defer book.Close()
    // Analyze the use of symbolism in clothing
    clothingSymbolism := make(map[string]int)
    scanner := bufio.NewScanner(book)
    for scanner.Scan() {
        line := scanner.Text()
        if strings.Contains(line, "clothing") || strings.Contains(line, "dress") {
            // Search for keywords related to symbolism
            if strings.Contains(line, "symbolism") || strings.Contains(line, "symbolic") {
                // Extract clothing item and update count in map
                clothing := extractClothing(line)
                if clothing != "" {
                    clothingSymbolism[clothing]++
                }
            }
        }
    }
    // Convert results to JSON
    jsonData, err := json.Marshal(clothingSymbolism)
    if err != nil {
        log.Fatal(err)
    }
    fmt.Println("Symbolism in clothing:")
    fmt.Println(string(jsonData))
}
func extractClothing(line string) string {
    // Extract clothing item from line
    // Example: "He wore a blue suit that symbolized his wealth."
    // Returns "blue suit"
    re := regexp.MustCompile(`wore a (\w+ \w+) that symbolized`)
    match := re.FindStringSubmatch(line)
    if len(match) > 1 {
        return match[1]
    }
    return ""
