    Name         string
    Price        float64
    MarketCap    float64
    Volume       float64
    GrowthFactor float64
}
func main() {
    cryptos := []Crypto{
        {"X", 0.01, 10000, 1000, 0},
        {"Y", 0.02, 5000, 500, 0},
        {"Z", 0.05, 20000, 2000, 0},
        {"A", 0.01, 2500, 100, 0},
        {"B", 0.03, 15000, 1500, 0},
        {"C", 0.01, 3000, 300, 0},
        {"D", 0.04, 12000, 1200, 0},
    }
    filteredCryptos := []Crypto{}
    for _, crypto := range cryptos {
        if crypto.MarketCap > 10000 && crypto.Volume > 1000 {
            filteredCryptos = append(filteredCryptos, crypto)
        }
    }
    maxGrowthFactor := 0.0
    recommendedCrypto := Crypto{}
    for _, crypto := range filteredCryptos {
        growthFactor := math.Log(crypto.MarketCap/crypto.Volume) / crypto.Price
        crypto.GrowthFactor = growthFactor
        if growthFactor > maxGrowthFactor {
            maxGrowthFactor = growthFactor
            recommendedCrypto = crypto
        }
    }
    fmt.Printf("Recommended cryptocurrency: %s, Growth Factor: %f\n", recommendedCrypto.Name, recommendedCrypto.GrowthFactor)
}
