    const int RESIDENTIAL_ENERGY = 20;
    const int COMMERCIAL_ENERGY = 30;
    const int TOTAL_ENERGY = 100;
    const int SOLAR_ENERGY = 10;
    const int WIND_ENERGY = 20;
    const int HOURS_PER_DAY = 8;
    // Define variables
    int solar_hours = 0;
    int wind_hours = 0;
    int non_renewable_energy = 0;
    // Calculate energy demand per hour for each building type
    double residential_demand = static_cast<double>(RESIDENTIAL_ENERGY) / (HOURS_PER_DAY * 2); // divided by 2 because there are two building types
    double commercial_demand = static_cast<double>(COMMERCIAL_ENERGY) / (HOURS_PER_DAY * 2);
    // Calculate energy production per hour for each renewable source
    double solar_production = static_cast<double>(SOLAR_ENERGY);
    double wind_production = static_cast<double>(WIND_ENERGY);
    // Calculate the maximum renewable energy that can be produced per day
    double max_renewable_energy = (solar_production + wind_production) * HOURS_PER_DAY;
    // Calculate the minimum non-renewable energy that must be used per day
    double min_non_renewable_energy = TOTAL_ENERGY - max_renewable_energy;
    // Check if the renewable sources can meet the energy demand
    if (max_renewable_energy >= TOTAL_ENERGY) {
        solar_hours = WIND_ENERGY >= RESIDENTIAL_ENERGY ? HOURS_PER_DAY : 0;
        wind_hours = HOURS_PER_DAY - solar_hours;
    } else {
        // Calculate the optimal distribution of renewable energy sources
        double solar_potential = solar_production * HOURS_PER_DAY;
        double wind_potential = wind_production * HOURS_PER_DAY;
        if (solar_potential >= residential_demand && wind_potential >= commercial_demand) {
            // Use solar for residential and wind for commercial
            solar_hours = ceil(residential_demand / solar_production);
            wind_hours = ceil(commercial_demand / wind_production);
        } else if (wind_potential >= residential_demand && solar_potential >= commercial_demand) {
            // Use wind for residential and solar for commercial
            wind_hours = ceil(residential_demand / wind_production);
            solar_hours = ceil(commercial_demand / solar_production);
        } else {
            // Use non-renewable energy sources
            non_renewable_energy = min_non_renewable_energy;
        }
    }
    // Print the results
    cout << "Solar hours: " << solar_hours << endl;
    cout << "Wind hours: " << wind_hours << endl;
    cout << "Non-renewable energy: " << non_renewable_energy << endl;
    return 0;
}
