```c++
#include <iostream>
#include <fstream>
#include <vector>
#include <algorithm>
#include <unordered_map>
using namespace std;
struct Country {
    string name;
    int count;
};
bool compareCountries(Country c1, Country c2) {
    return c1.count > c2.count;
}
int main() {
    unordered_map<string, int> sites;
    ifstream file("unesco_sites.txt");
    string line;
    while (getline(file, line)) {
        sites[line]++;
    }
    file.close();

    vector<Country> countries;
    for (auto site : sites) {
        if (site.second >= 50) {
            string country = site.first.substr(site.first.find_last_of("(") + 1, 2);
            bool found = false;
            for (auto& c : countries) {
                if (c.name == country) {
                    c.count += site.second;
                    found = true;
                    break;
                }
            }
            if (!found) {
                countries.push_back({country, site.second});
            }
        }
    }

    sort(countries.begin(), countries.end(), compareCountries);
    int top = min(3, (int)countries.size());
    for (int i = 0; i < top; i++) {
        cout << countries[i].name << " - " << countries[i].count << endl;
    }

    return 0;
}
```
This code reads in a file called "unesco_sites.txt" that contains a list of UNESCO World Heritage Sites along with their country names. It then counts the number of sites for each country and stores this information in an unordered map. The code then iterates through the map and creates a vector of Country structs for each country that has at least 50 UNESCO sites. The vector is sorted by the number of sites in descending order, and the top 3 countries are printed out along with their respective counts.
