        shape.perimeter = stof(token);
        getline(ss, token, ',');
        shape.radius = stof(token);
        getline(ss, token, ',');
        stringstream ss2(token);
        float angle;
        while (ss2 >> angle) {
            shape.angles.push_back(angle);
            if (ss2.peek() == ',') {
                ss2.ignore();
            }
        }
        dataset.push_back(shape);
        getline(ss, token, ',');
        labels.push_back(token);
    }
}
// Define function to split the dataset into training and testing sets
void SplitData(const vector<ShapeFeatures>& dataset, const vector<string>& labels, vector<ShapeFeatures>& trainset, vector<string>& trainlabels, vector<ShapeFeatures>& testset, vector<string>& testlabels, float split) {
    random_device rd;
    mt19937 g(rd());
    vector<int> indices(dataset.size());
    iota(indices.begin(), indices.end(), 0);
    shuffle(indices.begin(), indices.end(), g);
    int splitIndex = round(dataset.size() * split);
    trainset.resize(splitIndex);
    trainlabels.resize(splitIndex);
    testset.resize(dataset.size() - splitIndex);
    testlabels.resize(dataset.size() - splitIndex);
    for (int i = 0; i < splitIndex; ++i) {
        trainset[i] = dataset[indices[i]];
        trainlabels[i] = labels[indices[i]];
    }
    for (int i = splitIndex; i < dataset.size(); ++i) {
        testset[i - splitIndex] = dataset[indices[i]];
        testlabels[i - splitIndex] = labels[indices[i]];
    }
}
// Define function to calculate entropy of a set of labels
float Entropy(const vector<string>& labels) {
    int n = labels.size();
    if (n == 0) {
        return 0;
    }
    map<string, int> counts;
    for (auto label : labels) {
        counts[label]++;
    }
    float entropy = 0;
    for (auto count : counts) {
        float p = (float)count.second / n;
        entropy -= p * log2(p);
    }
    return entropy;
}
// Define function to calculate information gain
float InformationGain(const vector<string>& labels, const vector<int>& indices, float entropy) {
    int n = labels.size();
    vector<string> leftLabels, rightLabels;
    for (auto index : indices) {
        if (index < n / 2) {
            leftLabels.push_back(labels[index]);
        }
        else {
            rightLabels.push_back(labels[index]);
        }
    }
    float leftEntropy = Entropy(leftLabels);
    float rightEntropy = Entropy(rightLabels);
    float pLeft = (float)leftLabels.size() / n;
    float pRight = (float)rightLabels.size() / n;
    float informationGain = entropy - pLeft * leftEntropy - pRight * rightEntropy;
    return informationGain;
}
// Define function to find the best feature to split on
string BestFeature(const vector<ShapeFeatures>& dataset, const vector<string>& labels, const vector<int>& indices, const vector<string>& usedFeatures) {
    float entropy = Entropy(labels);
    int nFeatures = dataset[0].angles.size() + 3;
    float bestInformationGain = -1;
    string bestFeature;
    for (int i = 0; i < nFeatures; ++i) {
        if (find(usedFeatures.begin(), usedFeatures.end(), to_string(i)) != usedFeatures.end()) {
            continue;
        }
        vector<float> featureValues(indices.size());
        if (i == 0) {
            for (int j = 0; j < indices.size(); ++j) {
                featureValues[j] = dataset[indices[j]].area;
            }
        }
        else if (i == 1) {
            for (int j = 0; j < indices.size(); ++j) {
                featureValues[j] = dataset[indices[j]].perimeter;
            }
        }
        else if (i == 2) {
            for (int j = 0; j < indices.size(); ++j) {
                featureValues[j] = dataset[indices[j]].radius;
            }
        }
        else {
            int angleIndex = i - 3;
            for (int j = 0; j < indices.size(); ++j) {
                featureValues[j] = dataset[indices[j]].angles[angleIndex];
            }
        }
        vector<int> sortedIndices(indices.size());
        iota(sortedIndices.begin(), sortedIndices.end(), 0);
        sort(sortedIndices.begin(), sortedIndices.end(), [&](int a, int b) { return featureValues[a] < featureValues[b]; });
        vector<string> sortedLabels(indices.size());
        for (int j = 0; j < indices.size(); ++j) {
            sortedLabels[j] = labels[indices[sortedIndices[j]]];
        }
        float informationGain = InformationGain(sortedLabels, sortedIndices, entropy);
        if (informationGain > bestInformationGain) {
            bestInformationGain = informationGain;
            bestFeature = to_string(i);
        }
    }
    return bestFeature;
}
// Define function to split the data based on the best feature
vector<vector<int>> SplitData(const vector<ShapeFeatures>& dataset, const vector<string>& labels, const vector<int>& indices, const string& bestFeature) {
    vector<vector<int>> splitIndices(2);
    vector<float> featureValues(indices.size());
    if (bestFeature == "0") {
        for (int i = 0; i < indices.size(); ++i) {
            featureValues[i] = dataset[indices[i]].area;
        }
    }
    else if (bestFeature == "1") {
        for (int i = 0; i < indices.size(); ++i) {
            featureValues[i] = dataset[indices[i]].perimeter;
        }
    }
    else if (bestFeature == "2") {
        for (int i = 0; i < indices.size(); ++i) {
            featureValues[i] = dataset[indices[i]].radius;
        }
    }
    else {
        int angleIndex = stoi(bestFeature) - 3;
        for (int i = 0; i < indices.size(); ++i) {
            featureValues[i] = dataset[indices[i]].angles[angleIndex];
        }
    }
    float splitValue = featureValues[indices.size() / 2];
    for (int i = 0; i < indices.size(); ++i) {
        if (featureValues[i] <= splitValue) {
            splitIndices[0].push_back(indices[i]);
        }
        else {
            splitIndices[1].push_back(indices[i]);
        }
    }
    return splitIndices;
}
// Define function to train the decision tree classifier
void TrainDecisionTree(const vector<ShapeFeatures>& dataset, const vector<string>& labels, vector<string>& usedFeatures, int depth, string& node) {
    vector<int> indices(dataset.size());
    iota(indices.begin(), indices.end(), 0);
    vector<vector<int>> splitIndices = SplitData(dataset, labels, indices, node);
    if (splitIndices[0].size() == 0 || splitIndices[1].size() == 0 || depth == 0) {
        node = labels[indices[0]];
        return;
    }
    string leftNode = BestFeature(dataset, labels, splitIndices[0], usedFeatures);
    usedFeatures.push_back(leftNode);
    TrainDecisionTree(dataset, labels, usedFeatures, depth - 1, leftNode);
    string rightNode = BestFeature(dataset, labels, splitIndices[1], usedFeatures);
    usedFeatures.push_back(rightNode);
    TrainDecisionTree(dataset, labels, usedFeatures, depth - 1, rightNode);
    node = leftNode + "," + rightNode;
}

